import { useSocket } from '@/hooks/useSocket';
import { Wifi, WifiOff, Loader2, Users } from 'lucide-react';
import { cn } from '@/lib/utils';

export function ConnectionStatus() {
  const { isConnected, connectionError, connectionCount, reconnect } = useSocket();

  if (isConnected) {
    return (
      <div className="flex items-center gap-3">
        <div className="flex items-center gap-1.5 text-xs text-green-600 dark:text-green-400">
          <Wifi className="w-3 h-3" />
          <span className="hidden sm:inline">Connected</span>
        </div>
        {connectionCount > 1 && (
          <div className="flex items-center gap-1.5 text-xs text-blue-600 dark:text-blue-400 bg-blue-100 dark:bg-blue-500/20 px-2 py-0.5 rounded-full">
            <Users className="w-3 h-3" />
            <span>{connectionCount} {connectionCount === 1 ? 'user' : 'users'}</span>
          </div>
        )}
      </div>
    );
  }

  if (connectionError) {
    return (
      <button
        onClick={reconnect}
        className="flex items-center gap-1.5 text-xs text-red-600 dark:text-red-400 hover:text-red-700 dark:hover:text-red-300 transition-colors"
        title="Click to reconnect"
      >
        <WifiOff className="w-3 h-3" />
        <span className="hidden sm:inline">Offline - Click to retry</span>
      </button>
    );
  }

  return (
    <div className="flex items-center gap-1.5 text-xs text-yellow-600 dark:text-yellow-400">
      <Loader2 className="w-3 h-3 animate-spin" />
      <span className="hidden sm:inline">Connecting...</span>
    </div>
  );
}
